// recipe: item-motion-sample
// args: none
// returns: ok, worldItems, settled, moving, p50Sqr, p95Sqr, p50Spin, maxSqr, error, detail
//
// Answers why the world-item stream stays at full rate: for every standalone world item it reads the rigidbody's own
// velocity and spin, applies `ItemMotionState.IsSettled`'s thresholds, and reports how many items the host's throttle
// should be calling settled. A high "moving" count with tiny velocities means the noise floor is below what ground contact
// actually produces. Read-only.
//
// ONE LINE ON PURPOSE: the client's evaluator takes one top-level expression.
((System.Func<string>)(() => { var inv = System.Globalization.CultureInfo.InvariantCulture; var world = WorldGeneration.world; if (world == null) { return "{\"ok\":false,\"error\":\"no-world\"}"; } var found = UnityEngine.Object.FindObjectsOfType(typeof(Item)); var velocities = new System.Collections.Generic.List<float>(); var spins = new System.Collections.Generic.List<float>(); var settled = 0; var moving = 0; var worldItems = 0; var sleeping = 0; var simulated = 0; var movingSleeping = 0; for (var i = 0; i < found.Length; i++) { var item = found[i] as Item; if (item == null || item.rb == null) { continue; } var parent = item.transform.parent; if (parent != null && parent.GetComponentInParent<Body>() != null) { continue; } worldItems++; var sqr = item.rb.velocity.sqrMagnitude; var spin = UnityEngine.Mathf.Abs(item.rb.angularVelocity); velocities.Add(sqr); spins.Add(spin); if (item.rb.IsSleeping()) { sleeping++; } if (item.rb.simulated) { simulated++; } if (sqr < 0.01f && spin < 0.1f) { settled++; } else { moving++; if (item.rb.IsSleeping()) { movingSleeping++; } } } velocities.Sort(); spins.Sort(); var p50 = velocities.Count == 0 ? 0f : velocities[velocities.Count / 2]; var p95 = velocities.Count == 0 ? 0f : velocities[System.Math.Min(velocities.Count - 1, (int)(velocities.Count * 0.95))]; var p50Spin = spins.Count == 0 ? 0f : spins[spins.Count / 2]; var maxSqr = velocities.Count == 0 ? 0f : velocities[velocities.Count - 1]; return "{\"ok\":true,\"sleeping\":" + sleeping.ToString(inv) + ",\"simulated\":" + simulated.ToString(inv) + ",\"movingSleeping\":" + movingSleeping.ToString(inv) + ",\"worldItems\":" + worldItems.ToString(inv) + ",\"settled\":" + settled.ToString(inv) + ",\"moving\":" + moving.ToString(inv) + ",\"p50Sqr\":" + p50.ToString("0.0000", inv) + ",\"p95Sqr\":" + p95.ToString("0.0000", inv) + ",\"p50Spin\":" + p50Spin.ToString("0.0000", inv) + ",\"maxSqr\":" + maxSqr.ToString("0.0000", inv) + "}"; }))()